    <body name="ball pelvis" pos="0 -0.3 1.1">
      <geom type="box" size="0.07 0.09 0.04" rgba="0.6 0.6 0.6 1"/>
      <body name="ball thigh">
        <joint name="ball hip" type="ball" range="0 120" damping="0.4"/>
        <geom type="capsule" fromto="0 0 0 0 0 -0.42" size="0.05" mass="4" rgba="0.9 0.45 0.35 1"/>
        <body name="ball shin" pos="0 0 -0.42">
          <joint name="ball knee" type="ball" range="0 140" damping="0.15"/>
          <geom type="capsule" fromto="0 0 0 0 0 -0.42" size="0.04" mass="2.5" rgba="0.9 0.45 0.35 1"/>
        </body>
      </body>
    </body>
